import {industryRegistry,commodityRegistry} from './simulation-registry.js?v=babbc3d3950e';
import {resolveIndustryTuning} from './industry-tuning.js?v=babbc3d3950e';
import {formatMoney,toMicrogold} from './money.js?v=babbc3d3950e';
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
export class DevIndustryTuningPanel{
 constructor({parent,getWorld}){const root=el('details'),body=el('div'),type=el('select'),fields=el('div'),status=el('p'),save=el('button','Stage validated tuning for next restart'),reset=el('button','Restore selected type defaults');root.append(el('summary','Manufacturing balance'),body);body.append(el('p','Recipes and buffers: cargo units. Durations: simulation seconds. Price controls: ratios. Changes apply only after a full simulation restart; active batches and paid transfers keep their terms.'),type,fields,save,reset,status);parent.append(root);status.setAttribute('role','status');type.setAttribute('aria-label','Industry balance type');for(const d of industryRegistry.values().filter(d=>d.manufacturing))type.append(Object.assign(el('option',d.display_name),{value:d.id}));this.inputs=[];
  const render=()=>{fields.replaceChildren();this.inputs=[];let d;try{d=resolveIndustryTuning(getWorld()?.industryDefinitions??[]).get(type.value);}catch(error){status.textContent='Invalid industry configuration: '+error.message;return;}this.definition=structuredClone(d);
   const number=(label,path,unit,{money=false,boolean=false}={})=>{const row=el('label',label+' ('+unit+') '),input=el('input');let value=this.definition;for(const key of path)value=value[key];input.type=boolean?'checkbox':'number';if(boolean)input.checked=value;else{input.step=money?'.01':'any';input.value=money?formatMoney(value/1000000):String(value);}const initial=input.value;row.append(input);fields.append(row);this.inputs.push(()=>{let target=this.definition;for(const key of path.slice(0,-1))target=target[key];if(!money||input.value!==initial)target[path.at(-1)]=boolean?input.checked:money?toMicrogold(Number(input.value)):Number(input.value);});};
   for(const [index,r] of d.inputs.entries())number(commodityRegistry.get(r.commodity_id).name+' per batch',['inputs',index,'quantity_per_tick'],'cargo units');for(const [index,r] of d.outputs.entries())number(commodityRegistry.get(r.commodity_id).name+' per batch',['outputs',index,'quantity_per_tick'],'cargo units');for(const key of ['production_duration_seconds','construction_duration_seconds'])number(key.replaceAll('_',' '),['manufacturing',key],'seconds');number('Working capital',['manufacturing','working_capital_microgold'],'gold',{money:true});
   for(const key of ['input_buffer_targets','input_storage_capacities','output_storage_capacities','output_cost_weights'])for(const c of Object.keys(d.manufacturing[key]))number(c+' '+key.replaceAll('_',' '),['manufacturing',key,c],key==='output_cost_weights'?'ratio':'cargo units');for(const c of Object.keys(d.base_build_cost))number(c+' construction',['base_build_cost',c],'cargo units');for(const key of ['review_interval_seconds','bid_multiplier','maximum_bid_multiplier'])number('Procurement '+key.replaceAll('_',' '),['manufacturing','procurement',key],key.includes('seconds')?'seconds':'ratio');for(const key of ['review_interval_seconds','ask_multiplier','minimum_markup_fraction'])number('Selling '+key.replaceAll('_',' '),['manufacturing','selling',key],key.includes('seconds')?'seconds':'ratio');number('Enforce cost recovery floor',['manufacturing','selling','enforce_cost_floor'],'enabled',{boolean:true});
   const order=el('input');order.value=d.manufacturing.procurement.input_priority.join(',');const label=el('label','Procurement priority (commodity IDs, first served first) ');label.append(order);fields.append(label);this.inputs.push(()=>this.definition.manufacturing.procurement.input_priority=order.value.split(',').map(s=>s.trim()));};
  type.onchange=render;root.ontoggle=()=>{if(root.open)render();};save.onclick=()=>{try{for(const apply of this.inputs)apply();const p=Object.fromEntries(['id','inputs','outputs','base_build_cost','manufacturing'].map(k=>[k,structuredClone(this.definition[k])])),world=getWorld();if(!world)throw Error('Generate a world first');const overrides=[...(world.industryDefinitions??[]).filter(x=>x.id!==p.id),p];resolveIndustryTuning(overrides);world.industryDefinitions=overrides;status.textContent='Validated. Restart the simulation to apply; the running economy is unchanged.';}catch(error){status.textContent='Invalid configuration: '+error.message;}};reset.onclick=()=>{const world=getWorld();if(world)world.industryDefinitions=(world.industryDefinitions??[]).filter(d=>d.id!==type.value);render();status.textContent='Defaults staged for next full restart.';};
 }
}
